content:
:root {
  --bg-color: #f0f4f8;
  --container-bg: #ffffff;
  --text-color: #333333;
  --heading-color: #2c3e50;
  --subtext-color: #7f8c8d;
  --timer-color: #e74c3c;
  --score-color: #27ae60;
  --target-color: #2c3e50;
  --guide-color: #95a5a6;
  --border-color: #bdc3c7;
  --border-focus: #3498db;
  --focus-shadow: rgba(52, 152, 219, 0.3);
  --btn-bg: #3498db;
  --btn-hover: #2980b9;
  --stats-bg: #f8f9fa;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #1a1a1a;
    --container-bg: #2d2d2d;
    --text-color: #f0f0f0;
    --heading-color: #ffffff;
    --subtext-color: #b0b0b0;
    --timer-color: #ff6b6b;
    --score-color: #2ecc71;
    --target-color: #ffffff;
    --guide-color: #888888;
    --border-color: #555555;
    --border-focus: #3498db;
    --focus-shadow: rgba(52, 152, 219, 0.4);
    --btn-bg: #3498db;
    --btn-hover: #2980b9;
    --stats-bg: #3a3a3a;
  }
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background-color: var(--bg-color);
  color: var(--text-color);
}

.app-container {
  max-width: 600px;
  margin: 40px auto;
  padding: 24px;
  background: var(--container-bg);
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  text-align: center;
}

.header {
  margin-bottom: 24px;
}

.header h1 {
  font-size: 2rem;
  color: var(--heading-color);
  margin-bottom: 8px;
}

.header p {
  color: var(--subtext-color);
  font-size: 1rem;
}

.game-box {
  display: flex;
  flex-direction: column;
  gap: 20px;
  align-items: center;
}

.timer {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--timer-color);
}

.score {
  font-size: 1.2rem;
  color: var(--score-color);
  font-weight: bold;
}

.target-word {
  font-size: 2.5rem;
  letter-spacing: 2px;
  margin: 10px 0;
  color: var(--target-color);
  font-family: monospace;
}

.roma-guide {
  font-size: 1.2rem;
  color: var(--guide-color);
  font-family: monospace;
  margin-bottom: 10px;
}

.input-box {
  width: 100%;
  max-width: 400px;
  padding: 12px 16px;
  font-size: 1.5rem;
  border: 2px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  text-align: center;
  transition: border-color 0.2s;
  background-color: var(--container-bg);
  color: var(--text-color);
}

.input-box:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 5px var(--focus-shadow);
}

.btn {
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: bold;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--btn-bg);
  color: white;
}

.btn-primary:hover {
  background-color: var(--btn-hover);
}

.result-box {
  display: flex;
  flex-direction: column;
  gap: 20px;
  align-items: center;
}

.stats-row {
  display: flex;
  justify-content: space-around;
  width: 100%;
  max-width: 400px;
  background: var(--stats-bg);
  padding: 16px;
  border-radius: 8px;
  font-size: 1.1rem;
}

@media (max-width: 480px) {
  .app-container {
    margin: 16px;
    padding: 16px;
  }

  .header h1 {
    font-size: 1.5rem;
  }

  .target-word {
    font-size: 2rem;
  }

  .input-box {
    font-size: 1.2rem;
    padding: 10px 12px;
  }

  .stats-row {
    flex-direction: column;
    gap: 12px;
  }
}

/**
 * タイピングする単語の情報を表すインターフェース
 */
export interface WordItem {
  /** 単語の識別ID */
  id: string;
  /** 日本語の表示文字列 */
  japanese: string;
  /** ローマ字の入力文字列 */
  roman: string;
}

/**
 * ゲームの進行状態を表す型
 */
export type GameStatus = 'ready' | 'playing' | 'finished';

/**
 * ゲームの統計情報を表すインターフェース
 */
export interface GameStats {
  /** 正解した単語数 */
  correctWords: number;
  /** 総入力文字数（打鍵数） */
  totalTyped: number;
  /** ミスタイプ数 */
  missCount: number;
  /** プレイ時間（秒） */
  playTime: number;
}

import { useState, useEffect, useRef } from 'react';
import { WordItem } from '../types';

interface GameScreenProps {
  currentWord: WordItem;
  score: number;
  timeLeft: number;
  onCorrectInput: () => void;
}

export default function GameScreen({
  currentWord,
  score,
  timeLeft,
  onCorrectInput,
}: GameScreenProps) {
  const [input, setInput] = useState('');
  const [isError, setIsError] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
  }, [currentWord]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;

    // ローマ字の途中一致（プレフィックス）チェック
    if (currentWord.roman.startsWith(val)) {
      setInput(val);
      setIsError(false);

      if (val === currentWord.roman) {
        setInput('');
        onCorrectInput();
      }
    } else {
      // ミスタイプ時のフィードバック
      setIsError(true);
    }
  };

  return (
    <div className="game-box">
      <div className="timer">残り時間: {timeLeft}秒</div>
      <div className="score">スコア（打鍵数）: {score}</div>
      <div>
        <div className="target-word">{currentWord.japanese}</div>
        <div className="roma-guide">{currentWord.roman}</div>
      </div>
      <input
        ref={inputRef}
        type="text"
        className="input-box"
        style={{ borderColor: isError ? '#e74c3c' : undefined }}
        value={input}
        onChange={handleChange}
        placeholder="ここに入力..."
        autoComplete="off"
        spellCheck="false"
      />
    </div>
  );
}

import { WordItem } from '../types';

interface ResultScreenProps {
  score: number;
  totalTyped: number;
  onRestart: () => void;
}

export default function ResultScreen({
  score,
  totalTyped,
  onRestart,
}: ResultScreenProps) {
  const cpm = totalTyped; // 60秒間の総文字数（Characters Per Minute）

  const handleShare = () => {
    const text = `ローマ字タイピングゲームで ${totalTyped}文字打てました！ (正解数: ${score}問)`;
    if (navigator.share) {
      navigator.share({
        title: 'ローマ字タイピングゲーム結果',
        text: text,
        url: window.location.href,
      }).catch(() => {});
    } else {
      navigator.clipboard.writeText(text);
      alert('結果をクリップボードにコピーしました！');
    }
  };

  return (
    <div className="result-box">
      <h2>ゲーム終了！</h2>
      <div className="stats-row">
        <div>
          <p>正解単語数</p>
          <strong>{score} 問</strong>
        </div>
        <div>
          <p>総文字数</p>
          <strong>{totalTyped} 文字</strong>
        </div>
        <div>
          <p>速度 (CPM)</p>
          <strong>{cpm} 文字/分</strong>
        </div>
      </div>
      <div style={{ display: 'flex', gap: '12px', justifyContent: 'center' }}>
        <button className="btn btn-primary" onClick={onRestart}>
          もう一度プレイする
        </button>
        <button 
          className="btn" 
          style={{ backgroundColor: '#2ecc71', color: 'white' }} 
          onClick={handleShare}
        >
          結果をシェア
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { GameStatus } from './types';
import { WORDS } from './constants';
import GameScreen from './components/GameScreen';
import ResultScreen from './components/ResultScreen';
import './index.css';

export default function App() {
  const [status, setStatus] = useState<GameStatus>('ready');
  const [timeLeft, setTimeLeft] = useState(60);
  const [correctWordsCount, setCorrectWordsCount] = useState(0);
  const [totalTyped, setTotalTyped] = useState(0);
  const [currentWordIndex, setCurrentWordIndex] = useState(0);

  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (status === 'playing' && timeLeft > 0) {
      timer = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0 && status === 'playing') {
      setStatus('finished');
    }
    return () => clearInterval(timer);
  }, [status, timeLeft]);

  const startGame = () => {
    setStatus('playing');
    setTimeLeft(60);
    setCorrectWordsCount(0);
    setTotalTyped(0);
    setCurrentWordIndex(Math.floor(Math.random() * WORDS.length));
  };

  const handleCorrectInput = () => {
    const currentWord = WORDS[currentWordIndex];
    setCorrectWordsCount((prev) => prev + 1);
    setTotalTyped((prev) => prev + currentWord.roman.length);
    // 次のランダムな単語へ
    let nextIndex;
    do {
      nextIndex = Math.floor(Math.random() * WORDS.length);
    } while (nextIndex === currentWordIndex && WORDS.length > 1);
    setCurrentWordIndex(nextIndex);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1>ローマ字タイピングゲーム</h1>
        <p>60秒間で何文字打てるかな？</p>
      </header>

      {status === 'ready' && (
        <div className="game-box">
          <p>スタートボタンを押してゲームを開始してください。</p>
          <button className="btn btn-primary" onClick={startGame}>
            スタート
          </button>
        </div>
      )}

      {status === 'playing' && (
        <GameScreen
          currentWord={WORDS[currentWordIndex]}
          score={totalTyped}
          timeLeft={timeLeft}
          onCorrectInput={handleCorrectInput}
        />
      )}

      {status === 'finished' && (
        <ResultScreen
          score={correctWordsCount}
          totalTyped={totalTyped}
          onRestart={startGame}
        />
      )}
    </div>
  );
}
